use event_envelope::{BookDelta,BookLevel,BookSnapshot};use fixed_decimal::{Price,Quantity};use serde::{Deserialize,Serialize};use std::collections::BTreeMap;use thiserror::Error;
#[derive(Clone,Copy,Debug,Eq,PartialEq,Serialize,Deserialize)]#[serde(rename_all="snake_case")]pub enum BookHealth{Unsynchronized,Healthy,Gapped,ChecksumFailed,Stale,Quarantined}
#[derive(Clone)]pub struct OrderBook{bids:BTreeMap<Price,Quantity>,asks:BTreeMap<Price,Quantity>,sequence:u64,health:BookHealth,updated_monotonic_ns:u64,max_levels:usize}
impl OrderBook{pub fn new(max_levels:usize)->Self{Self{bids:BTreeMap::new(),asks:BTreeMap::new(),sequence:0,health:BookHealth::Unsynchronized,updated_monotonic_ns:0,max_levels:max_levels.max(1)}}pub fn apply_snapshot(&mut self,v:&BookSnapshot,now:u64)->Result<(),BookError>{validate(&v.bids,&v.asks,false,self.max_levels)?;let bids=v.bids.iter().map(|x|(x.price,x.quantity)).collect();let asks=v.asks.iter().map(|x|(x.price,x.quantity)).collect();maps(&bids,&asks)?;self.bids=bids;self.asks=asks;self.sequence=v.last_sequence;self.health=BookHealth::Healthy;self.updated_monotonic_ns=now;Ok(())}pub fn apply_delta(&mut self,v:&BookDelta,now:u64)->Result<(),BookError>{if self.health!=BookHealth::Healthy{return Err(BookError::Untrusted)}if v.first_sequence>self.sequence.saturating_add(1)||v.last_sequence<=self.sequence{self.health=BookHealth::Gapped;return Err(BookError::Gap)}let mut bids=self.bids.clone();let mut asks=self.asks.clone();for x in &v.bids{apply(&mut bids,x)}for x in &v.asks{apply(&mut asks,x)}if bids.len()+asks.len()>self.max_levels{return Err(BookError::Capacity)}maps(&bids,&asks)?;self.bids=bids;self.asks=asks;self.sequence=v.last_sequence;self.updated_monotonic_ns=now;Ok(())}pub fn validate_checksum<F:FnOnce(&Self)->String>(&mut self,expected:&str,f:F)->Result<(),BookError>{if f(self)==expected{Ok(())}else{self.health=BookHealth::ChecksumFailed;Err(BookError::Checksum)}}pub fn mark_stale(&mut self,now:u64,maximum:u64)->bool{if now.saturating_sub(self.updated_monotonic_ns)>maximum{self.health=BookHealth::Stale;true}else{false}}pub fn reset(&mut self){self.bids.clear();self.asks.clear();self.sequence=0;self.health=BookHealth::Unsynchronized}pub const fn health(&self)->BookHealth{self.health}pub const fn sequence(&self)->u64{self.sequence}pub fn best_bid(&self)->Option<Price>{self.bids.last_key_value().map(|x|*x.0)}pub fn best_ask(&self)->Option<Price>{self.asks.first_key_value().map(|x|*x.0)}}
fn apply(map:&mut BTreeMap<Price,Quantity>,x:&BookLevel){if x.quantity.value().is_zero(){map.remove(&x.price);}else{map.insert(x.price,x.quantity);}}fn validate(b:&[BookLevel],a:&[BookLevel],zero:bool,max:usize)->Result<(),BookError>{if b.len()+a.len()>max||(!zero&&b.iter().chain(a).any(|x|x.quantity.value().is_zero()))||!b.windows(2).all(|w|w[0].price>w[1].price)||!a.windows(2).all(|w|w[0].price<w[1].price){Err(BookError::Invalid)}else{Ok(())}}fn maps(b:&BTreeMap<Price,Quantity>,a:&BTreeMap<Price,Quantity>)->Result<(),BookError>{if b.is_empty()||a.is_empty()||b.last_key_value().zip(a.first_key_value()).is_some_and(|((x,_),(y,_))|x>=y){Err(BookError::Invalid)}else{Ok(())}}
#[derive(Debug,Error)]pub enum BookError{#[error("untrusted book")]Untrusted,#[error("sequence gap")]Gap,#[error("checksum mismatch")]Checksum,#[error("capacity exceeded")]Capacity,#[error("invalid book")]Invalid}
